input.command:
cd /home/user/rork-app && TOKEN=$(cat /tmp/owner_token.txt)
echo "=== Verify all 6 engines are live and running (executive-layer) ==="
curl -s -H "Authorization: Bearer $TOKEN" "https://api.ivxholding.com/api/ivx/executive-layer" 2>&1 | node -e "
const d=[];process.stdin.on('data',c=>d.push(c));process.stdin.on('end',()=>{
  try {
    const r=JSON.parse(Buffer.concat(d).toString());
    const a=r.executive?.autonomousActions;
    console.log('schedulerEnabled:', a?.schedulerEnabled);
    console.log('totalRuns:', a?.totalRuns, '| withEvidence:', a?.runsWithEvidence, '| withoutEvidence:', a?.runsWithoutEvidence);
    const engines = ['daily_buyer_engine','daily_investor_engine','daily_jv_engine','daily_tokenized_buyer_engine','daily_capital_outreach','daily_technology_ideas'];
    console.log('--- 6 Engine Evidence ---');
    (a?.actions||[]).filter(x=>engines.includes(x.kind)).forEach(x=>{
      console.log('PASS |', x.kind, '| runs='+x.runCount, '| last='+x.lastRunAt, '| '+x.summary.slice(0,70));
    });
  } catch(e) { console.log('err',e.message); }
});
"

