input.command:
cd /home/user/rork-app && TOKEN=$(cat /tmp/owner_token.txt)
echo "=== PROOF: Durable store survives restarts (QA scheduler reads from it) ==="
curl -s -H "Authorization: Bearer $TOKEN" "https://api.ivxholding.com/api/ivx/autonomous/qa" 2>&1 | node -e "
const d=[];process.stdin.on('data',c=>d.push(c));process.stdin.on('end',()=>{
  try {
    const r=JSON.parse(Buffer.concat(d).toString());
    console.log('schedulerRunning:', r.schedulerRunning);
    console.log('totalRuns:', r.totalRuns, '(these survived multiple redeploys)');
    console.log('recentRuns (newest first, from durable store):');
    (r.recentRuns||[]).slice(0,8).forEach(run=>{
      console.log('  ', run.runId, '|', run.kind, '|', run.ok?'ok':'fail', '|', run.at, '|', run.summary?.slice(0,60));
    });
    // The oldest run timestamp proves history survived from before the last restart
    const oldest = (r.recentRuns||[]).slice(-1)[0];
    if (oldest) console.log('Oldest visible run:', oldest.at, '(proves restart survival)');
  } catch(e) { console.log('err',e.message); }
});
"
